/* PMK 138 — Cartographie des adhérents
   Rapport SQL de ce Koha, géocodage IGN, carte dans le navigateur.
   Aucun numéro de rapport n’est imposé.
*/
(function(window){
    'use strict';
    if(!window.PMKPages || typeof window.PMKPages.register!=='function') return;
    const PAGE_SOURCE = "<style>\r\n#koha-carto-container{--oc-ink:#18283b;--oc-muted:#607185;--oc-border:#dfe6ed;--oc-blue:#1769aa;--oc-bg:#f3f6fa;--oc-surface:#fff; font-family:Inter,\"Segoe UI\",Arial,sans-serif!important;color:var(--oc-ink)!important;background:var(--oc-bg)!important;padding:18px!important;border:0!important;border-radius:14px!important;box-sizing:border-box;max-width:100%;}\r\n#koha-carto-container *,#koha-carto-container *::before,#koha-carto-container *::after{box-sizing:border-box}\r\n#koha-carto-container > div:first-child{background:linear-gradient(120deg,#112d49,#205b85)!important;border-radius:14px!important;padding:23px 25px!important;margin-bottom:15px!important;box-shadow:0 7px 20px rgba(14,44,70,.12)}\r\n#koha-carto-container > div:first-child h3{font-size:22px!important;line-height:1.35!important;letter-spacing:-.4px}\r\n#koha-carto-container > div:first-child p{font-size:13px!important;opacity:.85!important}\r\n#portable-config,#wizard-container,#filter-bar,#layers-control-bar,#legende-sites,#carto-stats-table-container{background:#fff!important;border:1px solid var(--oc-border)!important;border-radius:12px!important;box-shadow:0 2px 10px rgba(18,42,65,.04);margin-bottom:12px!important}\r\n#portable-config{padding:13px 17px!important}\r\n#portable-config summary{color:#223e5e;font-weight:700!important;padding:6px 1px;cursor:pointer;list-style-position:inside}\r\n#portable-config details[open]>summary{margin-bottom:9px}\r\n#portable-config label,#filter-bar label{font-size:12px!important;color:#3c536b}\r\n#portable-config input:not([type=checkbox]):not([type=color]):not([type=file]),#portable-config select,#portable-config textarea,#filter-bar select{border:1px solid #cbd6e2!important;border-radius:8px!important;padding:8px 10px!important;background:#fff!important;color:#20354a!important;min-height:34px}\r\n#portable-config input:focus,#portable-config select:focus,#filter-bar select:focus{outline:2px solid #a9cde6;outline-offset:1px}\r\n#koha-carto-container button{font-family:inherit!important;border-radius:8px!important;font-weight:650!important;transition:filter .15s,transform .15s!important;white-space:normal;min-height:35px}\r\n#koha-carto-container button:not(:disabled){cursor:pointer!important}\r\n#koha-carto-container button:not(:disabled):hover{filter:brightness(.94);transform:translateY(-1px)}\r\n#portable-config button{border:1px solid #d2dde8!important;background:#eef3f8!important;color:#234766!important;padding:8px 12px!important}\r\n#portable-save{background:#166ba8!important;color:#fff!important;border-color:#166ba8!important}\r\n#wizard-container{padding:17px!important;margin-bottom:12px!important}\r\n#wizard-container>b{display:block;color:#1d3853!important;font-size:16px!important;margin-bottom:5px}\r\n#wizard-container>p{margin-bottom:12px!important}\r\n#wizard-container>div:nth-of-type(1){background:#f5f8fc!important;border:1px solid #e5ebf2;border-radius:10px!important;padding:12px!important;gap:12px!important}\r\n#btn-step1,#btn-step2,#btn-step3{padding:10px 13px!important;font-size:12px!important;border-radius:8px!important}\r\n#btn-step1{background:#176ba5!important}\r\n#btn-step2:not(:disabled){background:#166f73!important}\r\n#btn-step3:not(:disabled){background:#6e48a4!important}\r\n#btn-step2:disabled,#btn-step3:disabled{opacity:.55}\r\n#carto-loader{padding:9px 11px!important;background:#edf5fa;border-radius:8px;color:#285875!important;font-size:12px!important}\r\n.carto-debug-details{margin-top:8px;font-size:12px;color:#6b7d8f}\r\n.carto-debug-details summary{cursor:pointer}\r\n#carto-debug-box{margin-top:7px!important}\r\n#koha-carto-container #tab-usagers,#koha-carto-container #tab-circulation{border:1px solid #d6e2ee!important;border-radius:9px!important;background:#f5f8fb!important;color:#46627d!important;padding:11px 20px!important;font-weight:700!important}\r\n#koha-carto-container #tab-usagers[style*=\"border-bottom: 3px\"],#koha-carto-container #tab-circulation[style*=\"border-bottom: 3px\"]{background:#185c91!important;color:white!important;border-color:#185c91!important}\r\n#koha-carto-container>div:has(>#tab-usagers){background:transparent!important;display:flex!important;gap:9px!important;padding:3px 0 11px!important}\r\n#filter-bar{padding:14px!important;gap:10px!important}\r\n#filter-bar select{margin:3px 0 0!important;min-width:200px!important;max-width:100%}\r\n#layers-control-bar{padding:12px 14px!important;gap:12px!important;font-size:12px!important}\r\n#layers-control-bar label{font-weight:500!important;background:#f4f7fb;border:1px solid #e8eef5;border-radius:8px;padding:7px 10px}\r\n#legende-sites{padding:12px 15px!important;gap:9px 17px!important;font-size:12px!important}\r\n#legende-sites>span{max-width:100%}\r\n#map{border:1px solid #dbe5ee!important;border-radius:12px!important;height:min(72vh,740px)!important;min-height:420px!important;margin-bottom:12px!important;overflow:hidden}\r\n#carto-stats-table-container{padding:15px!important}\r\n#stats-table-title{font-size:16px!important;color:#213d57!important}\r\n#carto-stats-table-container th{background:#edf3f9!important;color:#284c69!important}\r\n#carto-stats-table-container td,#carto-stats-table-container th{padding:10px!important}\r\n.carto-inner-details{background:#f8fafc;border:1px solid #e2eaf2;border-radius:10px;padding:10px 12px;margin:12px 0}\r\n.carto-help,.carto-muted{color:#6a7d8e;font-size:12px}\r\n.carto-color-actions{margin:8px 0}\r\n.carto-colors-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(205px,1fr));gap:8px;max-height:300px;overflow:auto}\r\n.carto-color-item{display:flex!important;align-items:center;gap:8px;padding:8px;border:1px solid #e5edf4;border-radius:9px;background:#fff;min-width:0}\r\n.carto-color-item input[type=color]{width:32px;height:32px;padding:2px;border:1px solid #d4dde7;border-radius:6px;cursor:pointer;flex-shrink:0}\r\n.carto-color-item span{min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:650}\r\n.carto-color-item small{font-size:10px;color:#7a8da0}\r\n@media(max-width:700px){#koha-carto-container{padding:8px!important}#koha-carto-container > div:first-child{padding:16px!important}#wizard-container>div:nth-of-type(1){flex-direction:column;align-items:stretch!important}#wizard-container>div:nth-of-type(1)>div:last-child{display:flex;flex-wrap:wrap}#filter-bar>div:first-child{width:100%}#filter-bar select{min-width:0!important;width:100%}#map{height:65vh!important}}\r\n</style>\r\n<div id=\"koha-carto-container\">\r\n<div style=\"background: #004085; color: white; padding: 15px; border-radius: 6px; margin-bottom: 20px;\">\r\n<h3 style=\"margin: 0 0 5px 0;\">Cartographie des adhérents</h3>\r\n<p style=\"margin: 0; font-size: 14px; opacity: 0.9;\">Outil d'aide à la décision pour l'analyse de l'activité du réseau de lecture publique et l'aménagement du territoire.</p>\r\n</div>\r\n<div id=\"portable-config\" style=\"background: #fff; border: 1px solid #ddd; border-radius: 6px; padding: 12px; margin: 12px 0;\"><details>\r\n<summary style=\"cursor: pointer; font-weight: bold;\">Réglages avancés · sites, données et couleurs</summary>\r\n<div style=\"display: flex; gap: 12px; flex-wrap: wrap; margin-top: 12px; align-items: end;\"><label>Rapport Koha<br /><input type=\"number\" id=\"portable-report\" min=\"0\" value=\"0\" style=\"padding: 6px; width: 105px;\" /></label> <label>Précision interne<br /><select id=\"portable-precision\">\r\n<option value=\"4\" selected=\"selected\">4 décimales (actuelle)</option>\r\n<option value=\"5\">5 décimales</option>\r\n</select></label> <label>Seuil minimal des cellules exportées<br /><input type=\"number\" id=\"portable-k\" min=\"2\" value=\"3\" style=\"width: 75px; padding: 6px;\" /></label> <button id=\"portable-save\" type=\"button\">Appliquer</button><button id=\"portable-export-config\" type=\"button\">Exporter la configuration</button> <label>Importer configuration <input type=\"file\" id=\"portable-import-config\" accept=\"application/json,.json\" /></label></div>\r\n<p style=\"font-size: 12px;\">Le numéro 0 ne lance aucune lecture. Le SQL à créer dans Koha se copie depuis Réglages de cette page. Les sites se masquent ici, pas dans le SQL.</p>\r\n<div style=\"margin: 12px 0; padding: 10px; border: 1px solid #dee2e6; border-radius: 5px;\"><b>Sites à exclure de l'observatoire</b>\r\n<p style=\"font-size: 12px; margin: 5px 0;\">Décochez les sites à masquer. L'exclusion s'applique à la carte, aux légendes, aux flux, aux statistiques et aux exports ; les données restent dans le rapport Koha.</p>\r\n<div style=\"display: flex; gap: 8px; margin: 8px 0;\"><button type=\"button\" id=\"portable-all-sites\">Tout inclure</button><button type=\"button\" id=\"portable-no-sites\">Tout exclure</button></div>\r\n<div id=\"portable-sites-list\" style=\"display: grid; grid-template-columns: repeat(auto-fit,minmax(220px,1fr)); gap: 6px; max-height: 250px; overflow: auto;\"><span style=\"color: #777;\">Chargement des sites Koha…</span></div>\r\n</div>\r\n<details class=\"carto-inner-details\" id=\"portable-colors-details\">\r\n<summary>Couleurs des médiathèques <span class=\"carto-muted\">(personnalisables)</span></summary>\r\n<p class=\"carto-help\">Chaque site reçoit une couleur différente par défaut. Les modifications sont locales à ce navigateur et peuvent être exportées avec la configuration.</p>\r\n<div class=\"carto-color-actions\"><button type=\"button\" id=\"portable-reset-colors\">Réinitialiser les couleurs</button></div>\r\n<div id=\"portable-colors-list\" class=\"carto-colors-list\">Chargement des sites…</div>\r\n</details>\r\n<p style=\"font-size: 12px;\">Le géocodage envoie les adresses au service IGN externe. Les points individuels sont conservés seulement en mémoire ; l'export exclut les cellules comptant moins que le seuil défini. Ne pas partager un ancien JSON non anonymisé.</p>\r\n<label>Sites complémentaires (un JSON par ligne : {\"id\":\"SITE\",\"name\":\"Lieu complémentaire\",\"lat\":46.6,\"lon\":2.5})</label> <textarea id=\"portable-extras\" rows=\"3\" style=\"display: block; width: 100%; font-family: monospace;\" placeholder=\"{&quot;id&quot;:&quot;SITE&quot;,&quot;name&quot;:&quot;Lieu complémentaire&quot;,&quot;lat&quot;:46.6,&quot;lon&quot;:2.5}\"></textarea>\r\n<div id=\"portable-config-status\" role=\"status\" style=\"margin-top: 7px; font-size: 12px;\"></div>\r\n</details></div>\r\n<div id=\"wizard-container\" style=\"background: #fff; border: 1px solid #b8daff; padding: 15px; margin-bottom: 20px; border-radius: 6px;\"><b style=\"color: #004085; font-size: 15px;\">Actualiser les données</b>\r\n<p style=\"margin: 5px 0 15px 0; font-size: 13px; color: #6c757d;\">Pour une utilisation quotidienne fluide, chargez votre fichier de carte précalculé. Pour mettre à jour la carte, suivez les étapes 1, 2 et 3.</p>\r\n<div style=\"display: flex; gap: 15px; align-items: center; flex-wrap: wrap; background: #f1f3f5; padding: 10px; border-radius: 4px;\">\r\n<div><label for=\"file-input\" style=\"display: block; font-size: 12px; font-weight: bold; margin-bottom: 3px;\">Ouvrir une carte enregistrée</label> <input type=\"file\" id=\"file-input\" accept=\".json\" style=\"font-size: 13px;\" /></div>\r\n<div style=\"border-left: 1px solid #dee2e6; height: 35px; margin: 0 10px;\"></div>\r\n<div style=\"display: flex; gap: 8px;\"><button id=\"btn-step1\" style=\"padding: 6px 12px; background: #28a745; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 12px; font-weight: bold;\">1 · Lire Koha</button> <button id=\"btn-step2\" style=\"padding: 6px 12px; background: #6c757d; color: white; border: none; border-radius: 4px; cursor: not-allowed; font-size: 12px;\" disabled=\"disabled\">2 · Géocoder les adresses</button> <button id=\"btn-step3\" style=\"padding: 6px 12px; background: #6c757d; color: white; border: none; border-radius: 4px; cursor: not-allowed; font-size: 12px;\" disabled=\"disabled\">3 · Exporter la carte</button></div>\r\n</div>\r\n<div id=\"carto-loader\" style=\"margin-top: 10px; font-weight: bold; color: #0056b3; font-size: 13px;\">Statut : En attente d'une action.</div>\r\n<details class=\"carto-debug-details\">\r\n<summary>Journal technique</summary>\r\n<div id=\"carto-debug-box\" style=\"margin-top: 10px; background: #222; color: #7fee1d; padding: 10px; border-radius: 4px; font-family: monospace; font-size: 11px; max-height: 100px; overflow-y: auto;\">[DEBUG SYSTEM] En attente d'une action pour analyser la structure...</div>\r\n</details>\r\n<div id=\"error-console\" style=\"display: none; background: #fff3cd; border: 1px solid #ffeeba; color: #856404; padding: 10px; border-radius: 4px; margin-top: 10px; max-height: 120px; overflow-y: auto; font-family: monospace; font-size: 12px;\"><b>Avertissements (adresses ou sites non localisés, ignorés sur la carte) :</b>\r\n<ul id=\"error-list\" style=\"margin: 5px 0 0 20px; padding: 0;\"></ul>\r\n</div>\r\n</div>\r\n<div style=\"display: flex; background: #dee2e6; padding: 5px 5px 0 5px; border-radius: 6px 6px 0 0; gap: 5px;\"><button id=\"tab-usagers\" style=\"padding: 10px 20px; border: none; background: #fff; font-weight: bold; border-radius: 5px 5px 0 0; cursor: pointer; border-bottom: 3px solid #007bff;\">Usagers</button> <button id=\"tab-circulation\" style=\"padding: 10px 20px; border: none; background: #e9ecef; font-weight: bold; border-radius: 5px 5px 0 0; cursor: pointer; color: #495057;\">Circulation des documents</button></div>\r\n<div id=\"filter-bar\" style=\"background: #fff; padding: 15px; border-left: 1px solid #ccc; border-right: 1px solid #ccc; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 15px; border-bottom: 1px solid #dee2e6;\">\r\n<div style=\"display: flex; gap: 15px; align-items: center; flex-wrap: wrap;\">\r\n<div><label for=\"site-filter\" style=\"font-weight: bold; font-size: 13px;\">Médiathèque</label><select id=\"site-filter\" style=\"padding: 6px; min-width: 180px; margin-left: 5px;\">\r\n<option value=\"all\">Toutes les médiathèques</option>\r\n</select></div>\r\n<div id=\"container-subflux\"><label for=\"flux-type\" style=\"font-weight: bold; font-size: 13px;\">Type de flux</label><select id=\"flux-type\" style=\"padding: 6px; margin-left: 5px;\">\r\n<option value=\"inscription\">Domiciles vers les sites d'inscription</option>\r\n<option value=\"transaction\">Domiciles vers les sites de consommation réelle</option>\r\n</select></div>\r\n</div>\r\n<div id=\"carto-legend\" style=\"background: #f8f9fa; padding: 8px 12px; border-radius: 4px; border: 1px solid #dee2e6; font-size: 12px; display: flex; gap: 10px; align-items: center; flex-wrap: wrap;\"><span style=\"color: #999;\">Intensité des flux : en attente d'affichage…</span></div>\r\n</div>\r\n<div id=\"layers-control-bar\" style=\"background: #f1f3f5; padding: 10px 15px; border-left: 1px solid #ccc; border-right: 1px solid #ccc; border-bottom: 1px solid #dee2e6; display: flex; flex-wrap: wrap; gap: 20px; align-items: center; font-size: 13px;\"><span style=\"font-weight: bold; color: #495057;\">Couches</span> <label style=\"display: inline-flex; align-items: center; gap: 5px; cursor: pointer; font-weight: 600;\"> <input type=\"checkbox\" id=\"chk-layer-communes\" checked=\"checked\" /> Couleurs des communes </label> <label style=\"display: inline-flex; align-items: center; gap: 5px; cursor: pointer; font-weight: 600;\"> <input type=\"checkbox\" id=\"chk-layer-flux\" checked=\"checked\" /> Lignes de flux </label> <label id=\"lbl-layer-clusters\" style=\"display: inline-flex; align-items: center; gap: 5px; cursor: pointer; font-weight: 600;\"> <input type=\"checkbox\" id=\"chk-layer-clusters\" checked=\"checked\" /> Secteurs (usagers) </label></div>\r\n<div id=\"legende-sites\" style=\"background: #fff; padding: 10px 15px; border-left: 1px solid #ccc; border-right: 1px solid #ccc; border-bottom: 1px solid #dee2e6; display: flex; flex-wrap: wrap; gap: 10px 16px; align-items: center; font-size: 12px;\"><span style=\"color: #999;\">Chargement des médiathèques…</span></div>\r\n<div id=\"map\" style=\"width: 100%; height: 800px; border: 1px solid #ccc; border-top: none; border-radius: 0; background: #e5e5e5;\"></div>\r\n<div id=\"carto-stats-table-container\" style=\"background: #fff; border: 1px solid #ccc; border-top: none; border-radius: 0 0 6px 6px; padding: 15px; font-size: 13px;\">\r\n<h4 id=\"stats-table-title\" style=\"margin: 0 0 10px 0; color: #004085;\">Statistiques de la vue</h4>\r\n<div style=\"overflow-x: auto; max-height: 250px;\">\r\n<table style=\"width: 100%; border-collapse: collapse; text-align: left;\">\r\n<thead id=\"stats-table-header\"></thead>\r\n<tbody id=\"stats-table-body\">\r\n<tr>\r\n<td style=\"padding: 8px; color: #999; text-align: center;\">Aucune donnée chargée ou visible à l'écran.</td>\r\n</tr>\r\n</tbody>\r\n<tfoot id=\"stats-table-footer\"></tfoot>\r\n</table>\r\n</div>\r\n</div>\r\n<script>\n(function() {\r\n    let KOHA_REPORT_ID = Number(window.PMKPagesSettings?.runtime('patron-map')?.reportId) || 0;\r\n    let PRECISION_RUE = 4;\r\n    let MIN_EXPORT_COUNT = 3;\r\n    let extraSites = [];\r\n    let libsFromKoha = [];\r\n    let geoQuality = {precis:0, approximatif:0, introuvable:0};\r\n    let EXCLUDED_SITES = [];\r\n\r\n    const RAYON_CLUSTER_PX = 110;\r\n    const ZOOM_MAX_CLUSTERING = 17;\r\n    const DIAMETRE_BULLE = 36;\r\n    const EPAISSEUR_FLUX_MIN = 2;\r\n    const EPAISSEUR_FLUX_MAX = 13;\r\n\r\n    const DEGRADE_FLUX = [\r\n        { p: 0,    c: [46, 204, 113] },\r\n        { p: 0.33, c: [241, 196, 15] },\r\n        { p: 0.66, c: [230, 126, 34] },\r\n        { p: 1,    c: [231, 76, 60] }\r\n    ];\r\n\r\n    function interpolerCouleurFlux(t) {\r\n        t = Math.max(0, Math.min(1, t));\r\n        let a = DEGRADE_FLUX[0], b = DEGRADE_FLUX[DEGRADE_FLUX.length - 1];\r\n        for (let i = 0; i < DEGRADE_FLUX.length - 1; i++) {\r\n            if (t >= DEGRADE_FLUX[i].p && t <= DEGRADE_FLUX[i + 1].p) { a = DEGRADE_FLUX[i]; b = DEGRADE_FLUX[i + 1]; break; }\r\n        }\r\n        const local = (b.p - a.p) > 0 ? (t - a.p) / (b.p - a.p) : 0;\r\n        const rgb = a.c.map((v, i) => Math.round(v + (b.c[i] - v) * local));\r\n        return `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;\r\n    }\r\n\r\n    const SITE_PALETTE = [\r\n        '#0072B2','#D55E00','#009E73','#CC79A7','#E69F00','#6B48B8',\r\n        '#C62828','#00838F','#708900','#9C27B0','#1565C0','#AD1457',\r\n        '#5D4037','#2E7D32','#EF6C00','#283593','#00897B','#8E24AA',\r\n        '#B71C1C','#607D00','#006064','#C2185B','#3949AB','#BF360C'\r\n    ];\r\n    const SITE_COLORS = {};\r\n    let customSiteColors = {};\r\n    let paletteSiteIds = [];\r\n    function couleurHexValide(v) {return typeof v==='string' && /^#[0-9a-fA-F]{6}$/.test(v);}\r\n    function reconstruirePalette() {\r\n        const ids = new Set([...libsFromKoha,...extraSites.map(s=>({library_id:s.id}))].map(s=>String(s.library_id||s.id||'')).filter(Boolean));\r\n        Object.keys(customSiteColors).forEach(id=>ids.add(id));\r\n        paletteSiteIds = [...ids].sort((a,b)=>a.localeCompare(b,'fr'));\r\n    }\r\n    function getSiteColor(id) {\r\n        id=String(id||'');\r\n        if (couleurHexValide(customSiteColors[id])) return customSiteColors[id];\r\n        const idx=paletteSiteIds.indexOf(id);\r\n        if (idx>=0) return SITE_PALETTE[idx % SITE_PALETTE.length];\r\n        let h=0;for(let i=0;i<id.length;i++)h=(h*31+id.charCodeAt(i))>>>0;\r\n        return SITE_PALETTE[h % SITE_PALETTE.length];\r\n    }\r\n    function rafraichirCouleursCarte() {\r\n        if (cartoReady) {dessinerIconesBibliotheques();rafraichirAffichageCarte();}\r\n        remplirListeCouleurs();\r\n    }\r\n    function remplirListeCouleurs() {\r\n        const parent=document.getElementById('portable-colors-list');if(!parent)return;\r\n        const all=new Map();\r\n        [...libsFromKoha,...extraSites.map(s=>({...s,library_id:s.id}))].forEach(s=>{\r\n            const id=String(s.library_id||s.id||'');if(id)all.set(id,String(s.name||id));\r\n        });\r\n        parent.replaceChildren();\r\n        [...all.entries()].sort((a,b)=>a[1].localeCompare(b[1],'fr')).forEach(([id,name])=>{\r\n            const line=document.createElement('label');line.className='carto-color-item';\r\n            const picker=document.createElement('input');picker.type='color';picker.value=getSiteColor(id);picker.title='Couleur de '+name;\r\n            const title=document.createElement('span');title.textContent=name;\r\n            const code=document.createElement('small');code.textContent=id;\r\n            picker.addEventListener('input',()=>{\r\n                customSiteColors[id]=picker.value;\r\n                if(cartoReady){dessinerIconesBibliotheques();rafraichirAffichageCarte();}\r\n            });\r\n            line.append(picker,title,code);parent.append(line);\r\n        });\r\n        if(!all.size)parent.textContent='Aucun site disponible pour le moment.';\r\n    }\r\n\r\n    const COMMUNE_TO_SITE_MAP = {};\r\n    const COMMUNE_PALETTE = ['#003f5c', '#1f77b4', '#2ca02c', '#9467bd', '#bcbd22', '#bc5090', '#08519c'];\r\n    function getCommuneColor(codeInsee, nomCommune) {\r\n        if (!nomCommune) return '#7f7f7f';\r\n        const nomNormalise = nomCommune.toUpperCase().normalize(\"NFD\").replace(/[\\u0300-\\u036f]/g, \"\").replace(/ST-/g, \"SAINT-\").trim();\r\n        if (COMMUNE_TO_SITE_MAP[nomNormalise]) { return getSiteColor(COMMUNE_TO_SITE_MAP[nomNormalise]); }\r\n        let num = parseInt(codeInsee, 10);\r\n        if (isNaN(num)) { num = 0; for (let i = 0; i < codeInsee.length; i++) num += codeInsee.charCodeAt(i); }\r\n        return COMMUNE_PALETTE[num % COMMUNE_PALETTE.length];\r\n    }\r\n\r\n    let map, clustersLayerGroup, flowsLayerGroup, librariesLayerGroup, communesLayerGroup;\r\n    let currentMode = 'usagers';\r\n    let mapUpdateTimeout;\r\n    let patronsRaw = [];\r\n    let circulationRaw = []; let finalMapData = { patrons: [], circulation: [] };\r\n    let cellulesInscription = [];\r\n    let cellulesTransaction = []; let indexActuel = null;\r\n    let sitesDejaSignales = new Set();\r\n    let librariesCache = {};\r\n\r\n    let cartoReady = false;\r\n    let initStarted = false;\r\n    const startupWarnings = [];\r\n    function afficherStatut(message) {\r\n        const el = document.getElementById('carto-loader');\r\n        if (el) el.textContent = message;\r\n        const debug = document.getElementById('carto-debug-box');\r\n        if (debug) debug.textContent = message;\r\n    }\r\n    function chargerCSS(url) {\r\n        return new Promise((resolve, reject) => {\r\n            const link = document.createElement('link'); link.rel='stylesheet';link.href=url;\r\n            link.onload=resolve;link.onerror=()=>reject(new Error('CSS inaccessible : '+url));\r\n            document.head.appendChild(link);\r\n        });\r\n    }\r\n    function chargerScript(url) {\r\n        return new Promise((resolve,reject)=>{\r\n            const script=document.createElement('script');script.src=url;script.async=false;\r\n            script.onload=resolve;script.onerror=()=>reject(new Error('Script inaccessible : '+url));\r\n            document.head.appendChild(script);\r\n        });\r\n    }\r\n    async function essayerSources(urls, check, label) {\r\n        if(check())return;\r\n        for(const url of urls){try{await chargerScript(url);if(check())return;}catch(e){startupWarnings.push(label+' : '+e.message);}}\r\n        throw new Error(label+' non disponible. Vérifier le réseau, la CSP ou le bloqueur de contenu.');\r\n    }\r\n    async function chargerCartographie() {\r\n        afficherStatut('Chargement des bibliothèques cartographiques…');\r\n        try {\r\n            await chargerCSS('https://unpkg.com/leaflet@1.9.4/dist/leaflet.css');\r\n        } catch(e) {\r\n            try{await chargerCSS('https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.css');}\r\n            catch(error){startupWarnings.push('Feuille de style Leaflet indisponible');}\r\n        }\r\n        await essayerSources([\r\n            'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js',\r\n            'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js',\r\n            'https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js'\r\n        ],()=>typeof window.L!=='undefined','Leaflet');\r\n        await essayerSources([\r\n            'https://unpkg.com/supercluster@8.0.1/dist/supercluster.min.js',\r\n            'https://cdn.jsdelivr.net/npm/supercluster@8.0.1/dist/supercluster.min.js'\r\n        ],()=>typeof window.Supercluster!=='undefined','Supercluster');\r\n    }\r\n    async function initialiserCarto() {\r\n        if (initStarted) return;\r\n        initStarted=true;\r\n        chargerConfigLocale();\r\n        brancherConfiguration();\r\n        document.getElementById('btn-step1').addEventListener('click', executerEtape1);\r\n        document.getElementById('btn-step2').addEventListener('click', executerEtape2);\r\n        document.getElementById('btn-step3').addEventListener('click', executerEtape3);\r\n        document.getElementById('file-input').addEventListener('change', chargerFichierDonnees);\r\n        try {await chargerCartographie();}\r\n        catch(e){afficherStatut('Carte indisponible : '+e.message+' — Lecture du rapport Koha disponible.');logErreur(e.message);return;}\r\n        try {map = L.map('map', { preferCanvas: true }).setView([46.6, 2.5], 6);}\r\n        catch(e){afficherStatut('Échec de création de la carte : '+e.message);logErreur(e.message);return;}\r\n        cartoReady=true;\r\n        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '© OpenStreetMap' }).addTo(map);\r\n        communesLayerGroup = L.layerGroup().addTo(map);\r\n        clustersLayerGroup = L.layerGroup().addTo(map);\r\n        flowsLayerGroup = L.layerGroup().addTo(map);\r\n        librariesLayerGroup = L.layerGroup().addTo(map);\r\n        chargerContoursCommunes();\r\n        dessinerIconesBibliotheques();\r\n        chargerBibliothequesDepuisAPI();\r\n        const tabUsagers = document.getElementById('tab-usagers');\r\n        const tabCirculation = document.getElementById('tab-circulation');\r\n        const lblClusters = document.getElementById('lbl-layer-clusters');\r\n        tabUsagers.addEventListener('click', () => {\r\n            currentMode = 'usagers';\r\n            tabUsagers.style.background = '#fff'; tabUsagers.style.borderBottom = '3px solid #007bff';\r\n            tabUsagers.style.color = '#333';\r\n            tabCirculation.style.background = '#e9ecef'; tabCirculation.style.borderBottom = 'none'; tabCirculation.style.color = '#495057';\r\n            document.getElementById('container-subflux').style.visibility = 'visible';\r\n            lblClusters.style.display = 'inline-flex';\r\n            gererVisibiliteGroupesParCheckboxes();\r\n            rafraichirAffichageCarte();\r\n        });\r\n        tabCirculation.addEventListener('click', () => {\r\n            currentMode = 'circulation';\r\n            tabCirculation.style.background = '#fff'; tabCirculation.style.borderBottom = '3px solid #007bff'; tabCirculation.style.color = '#333';\r\n            tabUsagers.style.background = '#e9ecef'; tabUsagers.style.borderBottom = 'none'; tabUsagers.style.color = '#495057';\r\n            document.getElementById('container-subflux').style.visibility = 'hidden';\r\n            lblClusters.style.display = 'none';\r\n            if (map.hasLayer(clustersLayerGroup)) map.removeLayer(clustersLayerGroup);\r\n            gererVisibiliteGroupesParCheckboxes();\r\n            rafraichirAffichageCarte();\r\n        });\r\n        document.getElementById('chk-layer-communes').addEventListener('change', gererVisibiliteGroupesParCheckboxes);\r\n        document.getElementById('chk-layer-flux').addEventListener('change', gererVisibiliteGroupesParCheckboxes);\r\n        document.getElementById('chk-layer-clusters').addEventListener('change', gererVisibiliteGroupesParCheckboxes);\r\n        document.getElementById('site-filter').addEventListener('change', () => rafraichirAffichageCarte());\r\n        document.getElementById('flux-type').addEventListener('change', () => rafraichirAffichageCarte());\r\n        afficherStatut('Carte initialisée. Vous pouvez lire le rapport Koha ou importer un fichier JSON.');\r\n        map.on('zoomend moveend', () => {\r\n            clearTimeout(mapUpdateTimeout);\r\n            mapUpdateTimeout = setTimeout(() => {\r\n                if (currentMode === 'usagers' && indexActuel) { rafraichirClustersEtFlux(); }\r\n                else { mettreAJourTableauStats(); }\r\n            }, 120);\r\n        });\r\n    }\r\n    window.addEventListener('unhandledrejection', e => { if(initStarted) logErreur('Erreur asynchrone : '+String(e.reason?.message||e.reason)); });\r\n    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initialiserCarto);\r\n    else initialiserCarto();\r\n\r\n    function gererVisibiliteGroupesParCheckboxes() {\r\n        if (document.getElementById('chk-layer-communes').checked) { if (!map.hasLayer(communesLayerGroup)) map.addLayer(communesLayerGroup); }\r\n        else { if (map.hasLayer(communesLayerGroup)) map.removeLayer(communesLayerGroup); }\r\n        if (document.getElementById('chk-layer-flux').checked) { if (!map.hasLayer(flowsLayerGroup)) map.addLayer(flowsLayerGroup); }\r\n        else { if (map.hasLayer(flowsLayerGroup)) map.removeLayer(flowsLayerGroup); }\r\n        if (currentMode === 'usagers' && document.getElementById('chk-layer-clusters').checked) { if (!map.hasLayer(clustersLayerGroup)) map.addLayer(clustersLayerGroup); }\r\n        else { if (map.hasLayer(clustersLayerGroup)) map.removeLayer(clustersLayerGroup); }\r\n    }\r\n\r\n    let lastDepartments = '';\r\n    async function chargerContoursCommunes() {\r\n        const departments = [...new Set(libsFromKoha.map(lib=> {\r\n            const pc=String(lib.postal_code||lib.zipcode||'').replace(/\\s/g,'');\r\n            if (!/^\\d{5}$/.test(pc)) return null;\r\n            if (pc.startsWith('97') || pc.startsWith('98')) return pc.slice(0,3);\r\n            if (pc.startsWith('20')) return Number(pc)<20190?'2A':'2B';\r\n            return pc.slice(0,2);\r\n        }).filter(Boolean))];\r\n        const key=departments.sort().join(',');\r\n        if (key===lastDepartments || !communesLayerGroup || typeof L==='undefined') return;\r\n        lastDepartments=key;\r\n        communesLayerGroup.clearLayers();\r\n        const checkbox=document.getElementById('chk-layer-communes');\r\n        checkbox.disabled=!departments.length;\r\n        checkbox.parentNode.title=departments.length?'Communes des départements des sites Koha':'Aucun code postal Koha disponible';\r\n        for (const dept of departments.slice(0,12)) {\r\n            try {\r\n                const r=await fetch(`https://geo.api.gouv.fr/departements/${encodeURIComponent(dept)}/communes?format=geojson&geometry=contour`);\r\n                if(!r.ok) throw new Error(`HTTP ${r.status}`);\r\n                const json=await r.json();\r\n                L.geoJSON(json,{\r\n                    style:f=>({color:'#555',weight:1,opacity:.65,fillColor:getCommuneColor(String(f.properties?.code||''),String(f.properties?.nom||'')),fillOpacity:.3}),\r\n                    onEachFeature:(f,layer)=>{if(f.properties?.nom)layer.bindTooltip(String(f.properties.nom));}\r\n                }).addTo(communesLayerGroup);\r\n            } catch(e) {logErreur(`Contours ${dept} non disponibles : ${e.message}`);}\r\n        }\r\n        if(departments.length>12)logErreur('Contours limités aux 12 premiers départements pour éviter une surcharge du navigateur.');\r\n        gererVisibiliteGroupesParCheckboxes();\r\n    }\r\n\nfunction mettreAJourTableauStats() {\r\n        const thead = document.getElementById('stats-table-header');\r\n        const tbody = document.getElementById('stats-table-body');\r\n        const tfoot = document.getElementById('stats-table-footer');\r\n        const titleEl = document.getElementById('stats-table-title');\r\n        if (!thead || !tbody || !tfoot) return;\r\n        if (currentMode === 'usagers') {\r\n            titleEl.innerText = \"Répartition des usagers dans la zone visible\";\r\n            const axeText = document.getElementById('flux-type').value === 'inscription' ? \"Médiathèque d'inscription\" : \"Médiathèque de consommation\";\r\n            thead.innerHTML = `<tr style=\"background: #f1f3f5; border-bottom: 2px solid #dee2e6;\"><th style=\"padding: 8px; font-weight: bold;\">${axeText}</th><th style=\"padding: 8px; font-weight: bold; text-align: right;\">Usagers visibles</th><th style=\"padding: 8px; font-weight: bold; text-align: right;\">Pourcentage</th></tr>`;\r\n            if (!indexActuel) { tbody.innerHTML = '<tr><td colspan=\"3\" style=\"padding: 8px; color: #999; text-align: center;\">Aucune donnée chargée.</td></tr>'; tfoot.innerHTML = ''; return; }\r\n            const b = map.getBounds();\r\n            const bbox = [b.getWest(), b.getSouth(), b.getEast(), b.getNorth()];\r\n            const zoom = Math.round(map.getZoom()); const clustersVisibles = indexActuel.getClusters(bbox, zoom);\r\n            const stats = {}; let totalVisible = 0;\r\n            clustersVisibles.forEach(c => { const sites = c.properties.sites || {}; Object.keys(sites).forEach(site => { stats[site] = (stats[site] || 0) + sites[site]; totalVisible += sites[site]; }); });\r\n            if (totalVisible === 0) { tbody.innerHTML = '<tr><td colspan=\"3\" style=\"padding: 8px; color: #999; text-align: center;\">Aucun usager dans le cadre actuel.</td></tr>'; tfoot.innerHTML = ''; return; }\r\n            const sortedSites = Object.keys(stats).sort((a, b) => stats[b] - stats[a]);\r\n            let htmlRows = '';\r\n            sortedSites.forEach(site => {\r\n                const count = stats[site]; const pct = ((count / totalVisible) * 100).toFixed(1);\r\n                const currentLib = librariesCache[site]; const name = currentLib ? currentLib.name : site; const color = getSiteColor(site);\r\n                htmlRows += `<tr style=\"border-bottom: 1px solid #dee2e6;\"><td style=\"padding: 8px;\"><span style=\"color:${color}; font-weight:bold; margin-right:5px;\">■</span>${name} (${site})</td><td style=\"padding: 8px; text-align: right; font-weight: 500;\">${count}</td><td style=\"padding: 8px; text-align: right; color: #6c757d;\">${pct}%</td></tr>`;\r\n            });\r\n            tbody.innerHTML = htmlRows;\r\n            tfoot.innerHTML = `<tr style=\"background: #e9ecef; font-weight: bold; border-top: 2px solid #dee2e6;\"><td style=\"padding: 8px;\">Total usagers visibles</td><td style=\"padding: 8px; text-align: right;\">${totalVisible}</td><td style=\"padding: 8px; text-align: right;\">100%</td></tr>`;\r\n        } else if (currentMode === 'circulation') {\r\n            titleEl.innerText = \"Volume d'échange dans la zone filtrée\";\r\n            thead.innerHTML = `<tr style=\"background: #f1f3f5; border-bottom: 2px solid #dee2e6;\"><th style=\"padding: 8px; font-weight: bold;\">Médiathèque d'origine</th><th style=\"padding: 8px; font-weight: bold;\">Médiathèque de destination</th><th style=\"padding: 8px; font-weight: bold; text-align: right;\">Documents transférés</th></tr>`;\r\n            const siteSelectionne = document.getElementById('site-filter').value;\r\n            const dataCirculation = finalMapData.circulation || [];\r\n            let totalDocuments = 0; let htmlRows = '';\r\n            const fluxFiltres = dataCirculation.filter(c => {\r\n                if (EXCLUDED_SITES.includes(c.source_bib) || EXCLUDED_SITES.includes(c.dest_bib)) return false;\r\n                if (siteSelectionne !== 'all' && c.source_bib !== siteSelectionne && c.dest_bib !== siteSelectionne) return false;\r\n                return parseInt(c.volume_circulation) > 0;\r\n            }).sort((a, b) => parseInt(b.volume_circulation) - parseInt(a.volume_circulation));\r\n            if (fluxFiltres.length === 0) { tbody.innerHTML = '<tr><td colspan=\"3\" style=\"padding: 8px; color: #999; text-align: center;\">Aucun échange de document sur cette sélection.</td></tr>'; tfoot.innerHTML = ''; return; }\r\n            fluxFiltres.forEach(c => {\r\n                const vol = parseInt(c.volume_circulation); totalDocuments += vol;\r\n                const libSrc = librariesCache[c.source_bib] ? librariesCache[c.source_bib].name : c.source_bib;\r\n                const libDst = librariesCache[c.dest_bib] ? librariesCache[c.dest_bib].name : c.dest_bib;\r\n                htmlRows += `<tr style=\"border-bottom: 1px solid #dee2e6;\"><td style=\"padding: 8px;\"><span style=\"color:${getSiteColor(c.source_bib)}; font-weight:bold; margin-right:5px;\">■</span>${libSrc} (${c.source_bib})</td><td style=\"padding: 8px;\"><span style=\"color:${getSiteColor(c.dest_bib)}; font-weight:bold; margin-right:5px;\">➔</span>${libDst} (${c.dest_bib})</td><td style=\"padding: 8px; text-align: right; font-weight: 500;\">${vol}</td></tr>`;\r\n            });\r\n            tbody.innerHTML = htmlRows;\r\n            tfoot.innerHTML = `<tr style=\"background: #e9ecef; font-weight: bold; border-top: 2px solid #dee2e6;\"><td colspan=\"2\" style=\"padding: 8px;\">Total des documents en transit</td><td style=\"padding: 8px; text-align: right;\">${totalDocuments}</td></tr>`;\r\n        }\r\n    }\r\n    const champ = (row, ...names) => {\r\n        for (const n of names) { const key = Object.keys(row).find(k => k.toLowerCase() === n.toLowerCase()); if (key !== undefined) return row[key] ?? ''; }\r\n        return '';\r\n    };\r\n    async function executerEtape1() {\r\n        logErreur('', true);\r\n        const status = document.getElementById('carto-loader');\r\n        if (!KOHA_REPORT_ID) { status.innerText = 'Indiquez le numéro du rapport Koha dans les réglages de cette page. 0 ne lance aucune lecture.'; return; }\r\n        status.innerText = 'Lecture du rapport Koha…';\r\n        patronsRaw = []; circulationRaw = [];\r\n        try {\r\n            const r = await fetch(`/cgi-bin/koha/svc/report?id=${encodeURIComponent(KOHA_REPORT_ID)}&annotated=1`, {credentials:'same-origin'});\r\n            if (!r.ok) throw new Error(`Koha HTTP ${r.status}`);\r\n            const rows = await r.json();\r\n            if (!Array.isArray(rows) || !rows.length || typeof rows[0] !== 'object' || Array.isArray(rows[0])) throw new Error('Rapport vide ou réponse non annotée');\r\n            const keys = Object.keys(rows[0]).map(k=>k.toLowerCase());\r\n            const required = ['row_type','address','zipcode','city','site_inscription','site_transaction','source_bib','dest_bib','volume_circulation'];\r\n            const missing = required.filter(k=>!keys.includes(k));\r\n            if (missing.length) throw new Error('Colonnes absentes : '+missing.join(', '));\r\n            for (const row of rows) {\r\n                const kind = String(champ(row,'row_type')).toLowerCase();\r\n                if (kind === 'patron') {\r\n                    patronsRaw.push({address:champ(row,'address'), zipcode:champ(row,'zipcode'),city:champ(row,'city'),\r\n                        site_inscription:champ(row,'site_inscription'),site_transaction:champ(row,'site_transaction') || champ(row,'site_inscription')});\r\n                } else if (kind === 'circulation') {\r\n                    circulationRaw.push({source_bib:champ(row,'source_bib'),dest_bib:champ(row,'dest_bib'),volume_circulation:champ(row,'volume_circulation')});\r\n                }\r\n            }\r\n            if (!patronsRaw.length && !circulationRaw.length) throw new Error('Aucune donnée reconnue');\r\n            document.getElementById('carto-debug-box').textContent = `Lecture : ${patronsRaw.length} usagers, ${circulationRaw.length} flux.`;\r\n            status.innerText = `Étape 1 réussie (${rows.length} lignes). Vérifier SvcMaxReportRows si le résultat semble incomplet.`; activerBoutonEtape('btn-step2');\r\n        } catch(e) { status.innerText = 'Erreur rapport : '+e.message; }\r\n    }\r\n    const GEO_MAX_RPS = 42;\r\n    const GEO_CONCURRENCY = 20;\r\n    const geoScheduler = { nextAt: 0, pauseUntil: 0, chain: Promise.resolve() };\r\n    const geoSleep = ms => new Promise(resolve => setTimeout(resolve, Math.max(0, ms)));\r\n    function reserverAppelGeo() {\r\n        const ticket = geoScheduler.chain.then(async () => {\r\n            const now = performance.now();\r\n            const target = Math.max(now, geoScheduler.nextAt, geoScheduler.pauseUntil);\r\n            geoScheduler.nextAt = target + 1000 / GEO_MAX_RPS;\r\n            if (target > now) await geoSleep(target - now);\r\n        });\r\n        geoScheduler.chain = ticket.catch(() => {});\r\n        return ticket;\r\n    }\r\n    function pauseGeo(milliseconds) {\r\n        geoScheduler.pauseUntil = Math.max(geoScheduler.pauseUntil, performance.now() + milliseconds);\r\n        geoScheduler.nextAt = Math.max(geoScheduler.nextAt, geoScheduler.pauseUntil);\r\n    }\r\n    async function geocoderAdresse(address) {\r\n        const url = new URL('https://data.geopf.fr/geocodage/search');\r\n        url.searchParams.set('index','address');\r\n        url.searchParams.set('q', address);\r\n        url.searchParams.set('limit','1');\r\n        for (let attempt=0; attempt<4; attempt++) {\r\n            await reserverAppelGeo();\r\n            try {\r\n                const r = await fetch(url.toString(), { signal: AbortSignal.timeout(20000) });\r\n                if (r.status === 429 || r.status >= 500) {\r\n                    const retry = Number(r.headers.get('retry-after'));\r\n                    const delay = Number.isFinite(retry) && retry > 0 ? Math.min(60000, retry * 1000) : Math.min(10000, 1500 * (attempt + 1));\r\n                    if (r.status === 429) pauseGeo(delay + 250);\r\n                    if (attempt === 3) throw new Error('IGN HTTP ' + r.status);\r\n                    await geoSleep(delay);\r\n                    continue;\r\n                }\r\n                if (!r.ok) throw new Error('Géocodage HTTP ' + r.status);\r\n                const json = await r.json();\r\n                const f = json.features?.[0];\r\n                if (!f || !Array.isArray(f.geometry?.coordinates)) return null;\r\n                const [lon,lat] = f.geometry.coordinates;\r\n                if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;\r\n                return {lat,lon,score:Number(f.properties?.score || 0),type:f.properties?.type || ''};\r\n            } catch(e) {\r\n                if (attempt === 3 || /^Géocodage HTTP 4\\d\\d/.test(e.message)) throw e;\r\n                await geoSleep(500 * (attempt+1));\r\n            }\r\n        }\r\n        return null;\r\n    }\r\n\nasync function executerEtape2() {\r\n        const status = document.getElementById('carto-loader');\r\n        const btn = document.getElementById('btn-step2');\r\n        if (btn.disabled) return;\r\n        btn.disabled = true;\r\n        const uniques = new Map();\r\n        geoQuality = {precis:0,approximatif:0,introuvable:0};\r\n        patronsRaw.forEach(p => {\r\n            const a = [p.address,p.zipcode,p.city].filter(Boolean).join(' ').trim();\r\n            if (!a) return;\r\n            if (!uniques.has(a)) uniques.set(a, []);\r\n            uniques.get(a).push(p);\r\n        });\r\n        const entries = Array.from(uniques.entries());\r\n        const total = entries.length;\r\n        const geocoded = [];\r\n        let cursor = 0, completed = 0, errors = 0;\r\n        const started = performance.now();\r\n        status.innerText = `Géocodage IGN : 0/${total} adresses uniques…`;\r\n        let lastRefresh = 0;\r\n        const progress = () => {\r\n            const now = performance.now();\r\n            if (completed < total && now - lastRefresh < 250) return;\r\n            lastRefresh = now;\r\n            const elapsed = Math.max(0.001, (now - started) / 1000);\r\n            const speed = (completed / elapsed).toFixed(1);\r\n            status.innerText = `IGN ${completed}/${total} (${speed} adresses/s) · précis ${geoQuality.precis} · approximatif ${geoQuality.approximatif} · introuvable ${geoQuality.introuvable} · erreurs réseau ${errors}`;\r\n        };\r\n        async function worker() {\r\n            while (cursor < total) {\r\n                const index = cursor++;\r\n                const [adr, users] = entries[index];\r\n                let result = null, failed = false;\r\n                try { result = await geocoderAdresse(adr); }\r\n                catch(e) { errors++; failed = true; if (errors <= 12) logErreur(`Erreur IGN pour une adresse : ${e.message}`); }\r\n                if (result) {\r\n                    const precise = result.type === 'housenumber' && result.score >= 0.75;\r\n                    geoQuality[precise ? 'precis' : 'approximatif'] += users.length;\r\n                    users.forEach(p => geocoded.push({lat:result.lat,lon:result.lon,site_inscription:p.site_inscription,site_transaction:p.site_transaction}));\r\n                } else if (!failed) geoQuality.introuvable += users.length;\r\n                completed++; progress();\r\n            }\r\n        }\r\n        try {\r\n            await Promise.all(Array.from({length:Math.min(GEO_CONCURRENCY,total)}, () => worker()));\r\n            if (errors > 0) logErreur(`${errors} adresse(s) en échec technique. Vérifiez les données avant export.`);\r\n            finalMapData = {patrons:geocoded,circulation:circulationRaw};\r\n            precalculerCellules();\r\n            if (cartoReady && map) rafraichirAffichageCarte();\r\n            activerBoutonEtape('btn-step3');\r\n            progress();\r\n            status.innerText += ` · Terminé en ${Math.round((performance.now()-started)/1000)} s`;\r\n        } catch(e) { status.innerText = 'Géocodage interrompu : ' + e.message; }\r\n        finally { btn.disabled = false; }\r\n    }\r\n    function creerExportAgrege() {\r\n        const groups=new Map();\r\n        for(const p of finalMapData.patrons) {\r\n            if(EXCLUDED_SITES.includes(String(p.site_inscription)) || EXCLUDED_SITES.includes(String(p.site_transaction))) continue;\r\n            const lat=Number(p.lat).toFixed(PRECISION_RUE),lon=Number(p.lon).toFixed(PRECISION_RUE);\r\n            const key=[lat,lon,p.site_inscription,p.site_transaction].join('|');\r\n            groups.set(key,(groups.get(key)||0)+Number(p.count||1));\r\n        }\r\n        const patrons=[];let masques=0;\r\n        for(const [key,count] of groups) {\r\n            if(count<MIN_EXPORT_COUNT) {masques+=count;continue;}\r\n            const [lat,lon,site_inscription,site_transaction]=key.split('|');\r\n            patrons.push({lat:+lat,lon:+lon,site_inscription,site_transaction,count});\r\n        }\r\n        return {format:'koha-cartographie-aggregate-v2',precision:PRECISION_RUE,min_count:MIN_EXPORT_COUNT,\r\n            supprimés:masques,patrons,circulation:finalMapData.circulation.filter(c=>!EXCLUDED_SITES.includes(String(c.source_bib))&&!EXCLUDED_SITES.includes(String(c.dest_bib)))};\r\n    }\r\n    function telechargerJSON(data,nom) {\r\n        const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});\r\n        const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=nom;a.click();\r\n        setTimeout(()=>URL.revokeObjectURL(url),3000);\r\n    }\r\n    function executerEtape3() {\r\n        if (!finalMapData.patrons.length && !finalMapData.circulation.length) return;\r\n        const data=creerExportAgrege();\r\n        telechargerJSON(data,'koha_observatoire_agrege.json');\r\n        document.getElementById('carto-loader').innerText=`Export agrégé : ${data.patrons.length} cellules ; ${data.supprimés} contributions exclues (seuil ${MIN_EXPORT_COUNT}).`;\r\n    }\r\n    function chargerFichierDonnees(e) {\r\n        const file=e.target.files[0]; if(!file)return;\r\n        const reader=new FileReader();\r\n        reader.onload=event=>{try {\r\n            const input=JSON.parse(event.target.result);\r\n            if(!Array.isArray(input.patrons)||!Array.isArray(input.circulation)) throw new Error('Structure invalide');\r\n            if(input.format && input.format!=='koha-cartographie-aggregate-v2') throw new Error('Format inconnu');\r\n            if(!input.format && !confirm('Ancien JSON : il peut contenir des points individuels. Importer seulement si ce fichier est autorisé ?'))return;\r\n            finalMapData={patrons:input.patrons,circulation:input.circulation};\r\n            precalculerCellules();rafraichirAffichageCarte();\r\n            document.getElementById('carto-debug-box').textContent='Import : '+finalMapData.patrons.length+' points / cellules';\r\n        }catch(e){alert('Import impossible : '+e.message);}};\r\n        reader.readAsText(file);\r\n    }\r\n    function precalculerCellules() {\r\n        sitesDejaSignales = new Set();\r\n        cellulesInscription = agregerParRue(finalMapData.patrons || [], 'site_inscription');\r\n        cellulesTransaction = agregerParRue(finalMapData.patrons || [], 'site_transaction');\r\n    }\r\n    function agregerParRue(patrons, champDestination) {\r\n        const cellules = {};\r\n        patrons.forEach(item => {\r\n            const dest = item[champDestination]; if (!dest || EXCLUDED_SITES.includes(dest)) return;\r\n            if (typeof item.lat !== 'number' || typeof item.lon !== 'number') return;\r\n            const latR = item.lat.toFixed(PRECISION_RUE); const lonR = item.lon.toFixed(PRECISION_RUE);\r\n            const key = `${latR}_${lonR}_${dest}`;\r\n            if (!cellules[key]) cellules[key] = { lat: parseFloat(latR), lon: parseFloat(lonR), dest, count: 0 };\r\n            cellules[key].count += Number(item.count || 1);\r\n        });\r\n        return Object.values(cellules);\r\n    }\r\n    function construireIndex(champFlux, filtreSite) {\r\n        const cellules = (champFlux === 'inscription') ? cellulesInscription : cellulesTransaction;\r\n        const points = cellules.filter(c => filtreSite === 'all' || c.dest === filtreSite).map(c => ({\r\n            type: 'Feature', properties: { count: c.count, sites: { [c.dest]: c.count } }, geometry: { type: 'Point', coordinates: [c.lon, c.lat] }\r\n        }));\r\n        const index = new Supercluster({\r\n            radius: RAYON_CLUSTER_PX, maxZoom: ZOOM_MAX_CLUSTERING, map: (props) => ({ count: props.count, sites: Object.assign({}, props.sites) }),\r\n            reduce: (acc, props) => { acc.count += props.count; Object.keys(props.sites).forEach(k => { acc.sites[k] = (acc.sites[k] || 0) + props.sites[k]; }); }\r\n        });\r\n        index.load(points); return { index, points };\r\n    }\r\n    function dessinerModeUsagers() {\r\n        const siteSelectionne = document.getElementById('site-filter').value;\r\n        const typeFlux = document.getElementById('flux-type').value;\r\n        const { index, points } = construireIndex(typeFlux, siteSelectionne); indexActuel = index;\r\n        if (points.length > 0) {\r\n            const bounds=L.latLngBounds(points.map(p=>[p.geometry.coordinates[1],p.geometry.coordinates[0]]));\r\n            map.fitBounds(bounds,{maxZoom:14});\r\n        }\r\n        rafraichirClustersEtFlux();\r\n    }\r\n    function rafraichirClustersEtFlux() {\r\n        clustersLayerGroup.clearLayers(); flowsLayerGroup.clearLayers();\r\n        if (currentMode !== 'usagers' || !indexActuel) { mettreAJourTableauStats(); return; }\r\n        const zoom = Math.round(map.getZoom()); const b = map.getBounds();\r\n        const bbox = [b.getWest(), b.getSouth(), b.getEast(), b.getNorth()];\r\n        const clusters = indexActuel.getClusters(bbox, zoom); const fluxAgreges = {};\r\n        const sitesSansPosition = new Set();\r\n        clusters.forEach(feature => {\r\n            const [lon, lat] = feature.geometry.coordinates; const props = feature.properties; const count = props.count; const sites = props.sites || {};\r\n            let siteDominant = null, maxVal = -1;\r\n            Object.keys(sites).forEach(s => { if (sites[s] > maxVal) { maxVal = sites[s]; siteDominant = s; } });\r\n            if (!siteDominant) return;\r\n            dessinerIconeCluster(lat, lon, count, sites, siteDominant);\r\n            const bib = librariesCache[siteDominant];\r\n            if (bib && typeof bib.lat === 'number' && typeof bib.lon === 'number') {\r\n                const key = `${lat.toFixed(4)}_${lon.toFixed(4)}_vers_${siteDominant}`;\r\n                fluxAgreges[key] = { from: [lat, lon], to: [bib.lat, bib.lon], count: maxVal, totalCluster: count, siteName: bib.name, sites };\r\n            } else sitesSansPosition.add(siteDominant);\r\n        });\r\n        sitesSansPosition.forEach(s => { if (!sitesDejaSignales.has(s)) { sitesDejaSignales.add(s); logErreur(`Aucune ligne de flux tracée vers \"${(librariesCache[s] && librariesCache[s].name) || s}\" (${s}) : position géographique inconnue.`); } });\r\n        const typeFlux = document.getElementById('flux-type').value;\r\n        creerLignesGraphiques(fluxAgreges, (typeFlux === 'inscription') ? \"sont inscrits à\" : \"consomment leurs services à\");\r\n        mettreAJourTableauStats();\r\n    }\r\n    function dessinerIconeCluster(lat, lon, count, sites, siteDominant) {\r\n        const diametre = DIAMETRE_BULLE;\r\n        const total = Object.values(sites).reduce((a, b) => a + b, 0);\r\n        const sitesTries = Object.keys(sites).sort((a, b) => sites[b] - sites[a]);\r\n        let acc = 0;\r\n        const parts = sitesTries.map(site => { const start = (acc / total) * 360; acc += sites[site]; const end = (acc / total) * 360; return `${getSiteColor(site)} ${start}deg ${end}deg`; }).join(', ');\r\n        const texteCount = count > 999 ? (count / 1000).toFixed(1) + 'k' : count;\r\n        const html = `<div style=\"width:${diametre}px;height:${diametre}px;border-radius:50%;background:conic-gradient(${parts});border:2px solid #fff;box-shadow:0 1px 5px rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;\"><span style=\"background:rgba(255,255,255,0.95);border-radius:9px;padding:1px 5px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#222;line-height:1.2;white-space:nowrap;\">${texteCount}</span></div>`;\r\n        const icon = L.divIcon({ html, className: '', iconSize: [diametre, diametre], iconAnchor: [diametre / 2, diametre / 2] });\r\n        const marker = L.marker([lat, lon], { icon });\r\n        const pourcentDominant = Math.round((sites[siteDominant] / total) * 100);\r\n        const detail = sitesTries.slice(0, 6).map(s => `<span style=\"color:${getSiteColor(s)}; font-weight:bold;\">■</span> ${(librariesCache[s] && librariesCache[s].name) || s} : <b>${sites[s]}</b>`).join('<br>');\r\n        marker.bindTooltip(`${count} usager(s) — ${pourcentDominant}% vers ${(librariesCache[siteDominant] && librariesCache[siteDominant].name) || siteDominant}`, { sticky: true });\r\n        marker.bindPopup(`<b>Secteur (${count} usager${count > 1 ? 's' : ''})</b><br>${detail}${sitesTries.length > 6 ? '<br>…' : ''}`);\r\n        marker.addTo(clustersLayerGroup);\r\n    }\r\n    function dessinerModeCirculation() {\r\n        const siteSelectionne = document.getElementById('site-filter').value;\r\n        const dataCirculation = finalMapData.circulation || [];\r\n        const fluxAgreges = {};\r\n        dataCirculation.forEach(c => {\r\n            if (EXCLUDED_SITES.includes(c.source_bib) || EXCLUDED_SITES.includes(c.dest_bib)) return;\r\n            if (siteSelectionne !== 'all' && c.source_bib !== siteSelectionne && c.dest_bib !== siteSelectionne) return;\r\n            const bibSource = librariesCache[c.source_bib]; const bibDest = librariesCache[c.dest_bib];\r\n            const sourceOk = bibSource && typeof bibSource.lat === 'number' && typeof bibSource.lon === 'number';\r\n            const destOk = bibDest && typeof bibDest.lat === 'number' && typeof bibDest.lon === 'number';\r\n            if (sourceOk && destOk) {\r\n                const key = `${bibSource.lat}_${bibSource.lon}_vers_${c.dest_bib}`;\r\n                if(!fluxAgreges[key]) fluxAgreges[key]={from:[bibSource.lat,bibSource.lon],to:[bibDest.lat,bibDest.lon],count:0,siteName:`de [${bibSource.name}] vers [${bibDest.name}]`};\r\n                fluxAgreges[key].count += Number(c.volume_circulation)||0;\r\n            } else if (!sourceOk && !sitesDejaSignales.has(c.source_bib)) { sitesDejaSignales.add(c.source_bib); logErreur(`Circulation ignorée : position inconnue pour le site \"${c.source_bib}\".`); }\r\n            else if (!destOk && !sitesDejaSignales.has(c.dest_bib)) { sitesDejaSignales.add(c.dest_bib); logErreur(`Circulation ignorée : position inconnue pour le site \"${c.dest_bib}\".`); }\r\n        });\r\n        creerLignesGraphiques(fluxAgreges, \"documents circulent depuis leur site d'origine vers\");\r\n        mettreAJourTableauStats();\r\n    }\r\n    function creerLignesGraphiques(fluxAgreges, texteLabel) {\r\n        const flux = Object.values(fluxAgreges).filter(f => f.count > 0);\r\n        if (flux.length === 0) { mettreAJourLegendeFlux(null, null); return; }\r\n        const volumes = flux.map(f => f.count);\r\n        const min = Math.min(...volumes); const max = Math.max(...volumes);\r\n        mettreAJourLegendeFlux(min, max); const logMin = Math.log(min); const logMax = Math.log(max);\r\n        flux.forEach(f => {\r\n            const volume = f.count; const t = (logMax > logMin) ? (Math.log(volume) - logMin) / (logMax - logMin) : 1;\r\n            const couleur = interpolerCouleurFlux(t); const epaisseur = EPAISSEUR_FLUX_MIN + t * (EPAISSEUR_FLUX_MAX - EPAISSEUR_FLUX_MIN);\r\n            L.polyline([f.from, f.to], { color: '#ffffff', weight: epaisseur + 3, opacity: 0.55, smoothFactor: 2.5 }).addTo(flowsLayerGroup);\r\n            const detailAutres = f.sites ? construireDetailAutresSites(f.sites, f.siteName) : '';\r\n            L.polyline([f.from, f.to], { color: couleur, weight: epaisseur, opacity: 0.85, smoothFactor: 2.5 })\r\n             .bindPopup(`<b>Volume du flux :</b><br><b>${volume} ${currentMode === 'circulation' ? 'documents' : 'usagers'}</b> ${texteLabel} <b>${f.siteName}</b>${detailAutres}`).addTo(flowsLayerGroup);\r\n        });\r\n    }\r\n    function mettreAJourLegendeFlux(min, max) {\r\n        const legend = document.getElementById('carto-legend');\r\n        if (!legend) return;\r\n        if (min === null) { legend.innerHTML = '<span style=\"color:#999;\">Aucun flux à afficher pour cette vue.</span>'; return; }\r\n        const degrade = 'linear-gradient(to right, rgb(46,204,113), rgb(241,196,15), rgb(230,126,34), rgb(231,76,60))';\r\n        legend.innerHTML = `<span style=\"font-weight:bold; color:#555;\">Intensité des flux (relative à la vue actuelle) :</span> <span style=\"font-weight:bold;\">${min}</span> <span style=\"display:inline-block; width:150px; height:11px; border-radius:6px; background:${degrade}; border:1px solid rgba(0,0,0,0.2);\"></span> <span style=\"font-weight:bold;\">${max}</span>`;\r\n    }\r\n    function construireDetailAutresSites(sites) {\r\n        const total = Object.values(sites).reduce((a, b) => a + b, 0);\r\n        const lignes = Object.keys(sites).sort((a, b) => sites[b] - sites[a]).slice(1, 5).map(s => `${(librariesCache[s] && librariesCache[s].name) || s} (${sites[s]})`).join(', ');\r\n        return `<br><span style=\"color:#666; font-size:11px;\">Reste du secteur (${total - Math.max(...Object.values(sites))} usagers) : ${lignes}</span>`;\r\n    }\r\n    function dessinerIconesBibliotheques() {\r\n        if (!librariesLayerGroup || typeof L==='undefined') return;\r\n        librariesLayerGroup.clearLayers();\r\n        Object.keys(librariesCache).forEach(id => {\r\n            const lib = librariesCache[id]; if (typeof lib.lat !== 'number' || typeof lib.lon !== 'number') return;\r\n            const couleur = getSiteColor(id);\r\n            const html = `<div style=\"width:26px;height:26px;transform:rotate(45deg);background:${couleur};border:3px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,0.5);\"></div>`;\r\n            const icon = L.divIcon({ html, className: '', iconSize: [26, 26], iconAnchor: [13, 13] });\r\n            const marker = L.marker([lib.lat, lib.lon], { icon, zIndexOffset: 1000 });\r\n            marker.bindPopup(`<b style=\"color:${couleur}; font-size:14px;\">Médiathèque : ${lib.name} (${id})</b>`);\r\n            marker.bindTooltip(`<b style=\"color:${couleur};\">${id}</b>`, { permanent: true, direction: 'right', offset: [12, 0], opacity: 0.9 });\r\n            marker.addTo(librariesLayerGroup);\r\n        });\r\n        mettreAJourLegendeSites();\r\n    }\r\n    function mettreAJourLegendeSites() {\r\n        const container = document.getElementById('legende-sites');\r\n        if (!container) return;\r\n        const ids = Object.keys(librariesCache); if (ids.length === 0) return;\r\n        ids.sort((a, b) => (librariesCache[a].name || a).localeCompare(librariesCache[b].name || b));\r\n        let html = '<span style=\"font-weight:bold; color:#555;\">Médiathèques du réseau :</span>';\r\n        ids.forEach(id => {\r\n            const lib = librariesCache[id]; const couleur = getSiteColor(id);\r\n            const positionInconnue = !(typeof lib.lat === 'number' && typeof lib.lon === 'number');\r\n            html += ` <span style=\"display:inline-flex; align-items:center; gap:5px;${positionInconnue ? ' opacity:0.55;' : ''}\"> <span style=\"width:13px; height:13px; border-radius:3px; background:${couleur}; display:inline-block; border:1px solid rgba(0,0,0,0.2);\"></span> ${lib.name || id}</span>`;\r\n        });\r\n        container.innerHTML = html;\r\n    }\r\n    function logErreur(message, reset = false) {\r\n        const consoleEl = document.getElementById('error-console');\r\n        const listEl = document.getElementById('error-list');\r\n        if (reset) { listEl.innerHTML = \"\"; consoleEl.style.display = \"none\"; return; }\r\n        consoleEl.style.display = \"block\"; const li = document.createElement('li'); li.innerText = message; listEl.appendChild(li);\r\n    }\r\n    function activerBoutonEtape(idBouton) {\r\n        const btn = document.getElementById(idBouton);\r\n        btn.disabled = false; btn.style.background = \"#007bff\"; btn.style.cursor = \"pointer\";\r\n    }\r\n    async function chargerBibliothequesDepuisAPI() {\r\n        try {\r\n            const libs=[]; let page=1;\r\n            while(page<=30) {\r\n                const r=await fetch(`/api/v1/libraries?_per_page=100&_page=${page}`,{credentials:'same-origin'});\r\n                if(!r.ok) throw new Error(`API Koha ${r.status}`);\r\n                const batch=await r.json(); if(!Array.isArray(batch))throw new Error('Réponse API non reconnue');\r\n                libs.push(...batch); if(batch.length<100) break; page++;\r\n            }\r\n            libsFromKoha=libs; await actualiserSites(); await chargerContoursCommunes();\r\n        } catch(e) {logErreur('Impossible de récupérer les sites Koha : '+e.message);await actualiserSites();}\r\n    }\r\n    function remplirListeExclusions() {\r\n        const box=document.getElementById('portable-sites-list');\r\n        const all=new Map();\r\n        for(const lib of [...libsFromKoha,...extraSites.map(x=>({...x,library_id:x.id}))]) {\r\n            const id=String(lib.library_id||lib.id||'').trim();\r\n            if(id)all.set(id,String(lib.name||id));\r\n        }\r\n        for(const id of EXCLUDED_SITES)if(!all.has(id))all.set(id,id+' (non trouvé dans Koha)');\r\n        box.replaceChildren();\r\n        for(const [id,name] of [...all.entries()].sort((a,b)=>a[1].localeCompare(b[1],'fr'))) {\r\n            const label=document.createElement('label');\r\n            label.style.cssText='display:flex;gap:7px;align-items:center;cursor:pointer;font-size:13px';\r\n            const cb=document.createElement('input');cb.type='checkbox';cb.value=id;cb.checked=!EXCLUDED_SITES.includes(id);\r\n            cb.className='portable-site-enabled';\r\n            const span=document.createElement('span');span.textContent=name+' ('+id+')';\r\n            label.append(cb,span);box.append(label);\r\n        }\r\n        if(!all.size)box.textContent='Aucun site récupéré : chargez la page sur Koha ou ajoutez un site complémentaire.';\r\n    }\r\n    function lireExclusions() {\r\n        return [...document.querySelectorAll('#portable-sites-list input.portable-site-enabled:not(:checked)')].map(cb=>cb.value);\r\n    }\r\n    async function actualiserSites() {\r\n        librariesCache={};\r\n        const filter=document.getElementById('site-filter');const previous=filter.value;\r\n        filter.innerHTML='<option value=\"all\">Toutes les médiathèques</option>';\r\n        const all=[...libsFromKoha, ...extraSites.map(x=>({...x,library_id:x.id}))];\r\n        reconstruirePalette();remplirListeExclusions();remplirListeCouleurs();\r\n        for(const lib of all) {\r\n            const id=String(lib.library_id || lib.id || ''); if(!id||EXCLUDED_SITES.includes(id))continue;\r\n            const name=lib.name||id;\r\n            const opt=document.createElement('option');opt.value=id;opt.textContent=name;filter.appendChild(opt);\r\n            let lat=Number(lib.lat ?? lib.latitude),lon=Number(lib.lon ?? lib.longitude);\r\n            if(lib.geolocation && (typeof lib.geolocation==='string')) {\r\n                const coords=lib.geolocation.split(',').map(Number);\r\n                if(coords.length===2&&coords.every(Number.isFinite)){lat=coords[0];lon=coords[1];}\r\n            } else if(lib.geolocation && typeof lib.geolocation==='object') {\r\n                lat=Number(lib.geolocation.lat ?? lib.geolocation.latitude);\r\n                lon=Number(lib.geolocation.lon ?? lib.geolocation.longitude);\r\n            }\r\n            if(Number.isFinite(lat)&&Number.isFinite(lon)&&lat!==0&&lon!==0) librariesCache[id]={lat,lon,name};\r\n            else librariesCache[id]={name};\r\n        }\r\n        filter.value=Array.from(filter.options).some(o=>o.value===previous)?previous:'all';\r\n        dessinerIconesBibliotheques();\r\n        const aGeocoder=all.filter(l=>!EXCLUDED_SITES.includes(String(l.library_id||l.id))).filter(l=>!Number.isFinite(librariesCache[l.library_id]?.lat)).map(l=>({id:l.library_id,name:l.name,\r\n            adresse:[l.address1,l.address2,l.postal_code||l.zipcode,l.city].filter(Boolean).join(' ')})).filter(l=>l.adresse);\r\n        if(aGeocoder.length) await geocoderBibliotheques(aGeocoder);\r\n        const coords=Object.values(librariesCache).filter(l=>Number.isFinite(l.lat)&&Number.isFinite(l.lon));\r\n        if(coords.length&&cartoReady&&map)map.fitBounds(coords.map(l=>[l.lat,l.lon]),{padding:[30,30],maxZoom:13});\r\n        if(cartoReady&&map)rafraichirAffichageCarte();\r\n    }\r\n    async function geocoderBibliotheques(liste) {\r\n        let index = 0;\r\n        async function worker() {\r\n            while (index < liste.length) {\r\n                const l = liste[index++];\r\n                try {const p=await geocoderAdresse(l.adresse);if(p)librariesCache[l.id]={lat:p.lat,lon:p.lon,name:l.name};}\r\n                catch(e) {logErreur('Géocodage établissement '+l.name+' : '+e.message);}\r\n            }\r\n        }\r\n        await Promise.all(Array.from({length:Math.min(8,liste.length)},()=>worker()));\r\n        dessinerIconesBibliotheques();\r\n    }\r\n    function chargerConfigLocale() {\r\n        let c={};\r\n        try {c=JSON.parse(localStorage.getItem('koha-cartographie-config-v2')||'{}');} catch(e) {console.warn('Configuration locale invalide',e);}\r\n        const pageRuntime=window.PMKPagesSettings?.runtime('patron-map')||{};\r\n        KOHA_REPORT_ID=Number(pageRuntime.reportId)||Number(c.report)||0;\r\n        PRECISION_RUE=[4,5].includes(Number(c.precision))?Number(c.precision):([4,5].includes(Number(pageRuntime.precision))?Number(pageRuntime.precision):4);\r\n        MIN_EXPORT_COUNT=Math.max(2,Number(c.k)||Number(pageRuntime.minCount)||3);\r\n        extraSites=Array.isArray(c.extraSites)?c.extraSites:[];\r\n        EXCLUDED_SITES=Array.isArray(c.excludedSites)?[...new Set(c.excludedSites.map(String))]:[];\r\n        customSiteColors=(c.siteColors&&typeof c.siteColors==='object'&&!Array.isArray(c.siteColors))?Object.fromEntries(Object.entries(c.siteColors).filter(([,v])=>couleurHexValide(v))):{};\r\n        document.getElementById('portable-report').value=KOHA_REPORT_ID;\r\n        document.getElementById('portable-precision').value=PRECISION_RUE;\r\n        document.getElementById('portable-k').value=MIN_EXPORT_COUNT;\r\n        document.getElementById('portable-extras').value=extraSites.map(v=>JSON.stringify(v)).join('\\n');\r\n        reconstruirePalette();remplirListeExclusions();remplirListeCouleurs();\r\n    }\r\n    function lireConfigFormulaire() {\r\n        const report=Number(document.getElementById('portable-report').value);\r\n        if(!Number.isInteger(report)||report<0)throw new Error('Rapport invalide');\r\n        const precision=Number(document.getElementById('portable-precision').value);\r\n        const k=Number(document.getElementById('portable-k').value);\r\n        if(!Number.isInteger(k)||k<2)throw new Error('Seuil minimal : 2');\r\n        const lines=document.getElementById('portable-extras').value.split('\\n').map(l=>l.trim()).filter(Boolean);\r\n        const extras=lines.map(line=>JSON.parse(line));\r\n        for(const e of extras)if(!e.id||!e.name||!Number.isFinite(Number(e.lat))||!Number.isFinite(Number(e.lon)))throw new Error('Site complémentaire invalide');\r\n        return {report,precision,k,extraSites:extras,excludedSites:lireExclusions(),siteColors:{...customSiteColors}};\r\n    }\r\n    async function memoriserRapport(c) {\r\n        const tools=window.PMKConfig;\r\n        if(!tools?.getConfig||!tools.saveConfig)return;\r\n        const stored=await tools.getConfig('internal-pages-tools');\r\n        const next=stored&&typeof stored==='object'?stored:{enabled:true,hubAccess:'superlibrarian',pageOptions:{}};\r\n        next.pageOptions=next.pageOptions||{};\r\n        next.pageOptions['patron-map']=next.pageOptions['patron-map']||{};\r\n        next.pageOptions['patron-map'].runtime=Object.assign({}, next.pageOptions['patron-map'].runtime, {reportId:c.report, precision:c.precision, minCount:c.k});\r\n        await tools.saveConfig('internal-pages-tools', next);\r\n    }\r\n    function brancherConfiguration() {\r\n        document.getElementById('portable-reset-colors').addEventListener('click',()=>{\r\n            customSiteColors={};reconstruirePalette();rafraichirCouleursCarte();\r\n            document.getElementById('portable-config-status').textContent='Couleurs réinitialisées. Cliquez sur Appliquer pour enregistrer.';\r\n        });\r\n        document.getElementById('portable-all-sites').addEventListener('click',()=>{\r\n            document.querySelectorAll('#portable-sites-list input').forEach(x=>x.checked=true);\r\n        });\r\n        document.getElementById('portable-no-sites').addEventListener('click',()=>{\r\n            document.querySelectorAll('#portable-sites-list input').forEach(x=>x.checked=false);\r\n        });\r\n        document.getElementById('portable-save').addEventListener('click',async()=>{\r\n            const status=document.getElementById('portable-config-status');\r\n            try {const c=lireConfigFormulaire();\r\n                KOHA_REPORT_ID=c.report;PRECISION_RUE=c.precision;MIN_EXPORT_COUNT=c.k;extraSites=c.extraSites;EXCLUDED_SITES=c.excludedSites;customSiteColors=c.siteColors;reconstruirePalette();\r\n                localStorage.setItem('koha-cartographie-config-v2',JSON.stringify(c));\r\n                try{await memoriserRapport(c);}catch(saveError){console.warn(saveError);}\r\n                await actualiserSites();precalculerCellules();rafraichirCouleursCarte();\r\n                status.textContent='Configuration appliquée : ' + EXCLUDED_SITES.length + ' site(s) exclu(s).';\r\n            }catch(e){status.textContent='Erreur : '+e.message;}\r\n        });\r\n        document.getElementById('portable-export-config').addEventListener('click',()=>{\r\n            try{telechargerJSON(lireConfigFormulaire(),'koha_cartographie_configuration.json');}catch(e){alert(e.message);}\r\n        });\r\n        document.getElementById('portable-import-config').addEventListener('change',e=>{\r\n            const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{\r\n                try {const c=JSON.parse(r.result);document.getElementById('portable-report').value=c.report||0;\r\n                    document.getElementById('portable-precision').value=c.precision||4;\r\n                    document.getElementById('portable-k').value=c.k||3;\r\n                    document.getElementById('portable-extras').value=(c.extraSites||[]).map(x=>JSON.stringify(x)).join('\\n');\r\n                    EXCLUDED_SITES=Array.isArray(c.excludedSites)?c.excludedSites.map(String):[];customSiteColors=(c.siteColors&&typeof c.siteColors==='object')?Object.fromEntries(Object.entries(c.siteColors).filter(([,v])=>couleurHexValide(v))):{};reconstruirePalette();remplirListeExclusions();remplirListeCouleurs();\r\n                    document.getElementById('portable-config-status').textContent='Configuration importée ; cliquez Appliquer.';\r\n                }catch(err){alert('Configuration invalide : '+err.message);}};r.readAsText(file);\r\n        });\r\n    }\r\n    function rafraichirAffichageCarte() {\r\n        if (!cartoReady || !clustersLayerGroup || !flowsLayerGroup) return;\r\n        clustersLayerGroup.clearLayers(); flowsLayerGroup.clearLayers();\r\n        if (currentMode === 'usagers') dessinerModeUsagers();\r\n        else if (currentMode === 'circulation') dessinerModeCirculation();\r\n    }\r\n\n})();\n\n</script>\r\n</div>\r\n";
    window.PMKPages.register({
        id:"patron-map",
        title:"Cartographie des adhérents",
        async mount(container, context){
            await context.mountLegacyHtml(container, PAGE_SOURCE);
        }
    });
})(window);
